import{_ as d,a8 as r,o as p,c as k,ah as S,a,a3 as t,K as l,L as o}from"./chunks/framework.BIHr6la-.js";import"./chunks/theme.1k7pnZ2N.js";const c=JSON.parse('{"title":"DeepSeek NSA 稀疏注意力","description":"","frontmatter":{"title":"DeepSeek NSA 稀疏注意力","created":"2026-07-17T00:00:00.000Z","tags":["AI","DeepSeek","注意力机制","长上下文"],"type":"概念解释","related":["[[DeepSeek]]","[[DeepSeek 开源周五大工具]]","[[Transformer]]"],"reference":["[[DeepSeek技术发展详细时间轴与技术核心解析]]"],"category":["🤖 AI大模型"]},"headers":[],"relativePath":"vault/Knowledge/AI/DeepSeek NSA 稀疏注意力.md","filePath":"vault/Knowledge/AI/DeepSeek NSA 稀疏注意力.md","lastUpdated":1784459023000}'),h={name:"vault/Knowledge/AI/DeepSeek NSA 稀疏注意力.md"};function g(b,e,f,N,A,_){const n=r("VPNolebaseInlineLinkPreview"),s=r("NolebaseGitContributors"),i=r("NolebaseGitChangelog");return p(),k("div",null,[e[6]||(e[6]=S('<h1 id="deepseek-nsa-稀疏注意力" tabindex="-1">DeepSeek NSA 稀疏注意力 <a class="header-anchor" href="#deepseek-nsa-稀疏注意力" aria-label="Permalink to “DeepSeek NSA 稀疏注意力”">​</a></h1><blockquote><p>NSA（Native Sparse Attention，原生稀疏注意力）是 DeepSeek 于 2025 年 2 月提出的稀疏注意力机制，核心价值是<strong>让稀疏注意力在训练和推理阶段保持一致</strong>，从而在长上下文场景显著降本增效。</p></blockquote><h2 id="解决的核心问题" tabindex="-1">解决的核心问题 <a class="header-anchor" href="#解决的核心问题" aria-label="Permalink to “解决的核心问题”">​</a></h2><p>传统稀疏注意力常见的痛点是<strong>训练与推理割裂</strong>：训练时用稠密注意力、推理时才切稀疏，导致推理阶段模型能力下降。NSA 的「Native（原生）」正指它在训练阶段就以稀疏形态参与，训练推理统一，避免能力损失。</p><h2 id="三个「同时」" tabindex="-1">三个「同时」 <a class="header-anchor" href="#三个「同时」" aria-label="Permalink to “三个「同时」”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">NSA 的做法</th></tr></thead><tbody><tr><td style="text-align:left;">训练 vs 推理</td><td style="text-align:left;">同一套稀疏机制贯穿训练与推理，不产生能力落差</td></tr><tr><td style="text-align:left;">预填充 vs 解码</td><td style="text-align:left;">同时作用于 prefill（预填充）与 decode（解码）阶段，兼顾长文摘要与长代码输出</td></tr><tr><td style="text-align:left;">架构兼容</td><td style="text-align:left;">与 GQA、MQA 等高效注意力架构兼容，可叠加降本</td></tr></tbody></table><h2 id="效果-64k-上下文" tabindex="-1">效果（64K 上下文） <a class="header-anchor" href="#效果-64k-上下文" aria-label="Permalink to “效果（64K 上下文）”">​</a></h2><ul><li>后向传播（训练反向）速度提升约 <strong>6 倍</strong></li><li>前向传播速度提升约 <strong>9 倍</strong></li><li>解码速度提升约 <strong>11.6 倍</strong></li><li>长上下文推理成本显著下降，且推理任务性能不降反升</li></ul><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to “定位”">​</a></h2><p>NSA 属于 [[DeepSeek]] 在「模型架构创新」上的一环，与 MLA（省 KV 显存）、MoE（省激活算力）互补：MLA/MoE 优化的是「算什么、存什么」，NSA 优化的是「注意力算多少」。</p><blockquote><p>⚠️ 时效：数据来自 2025-05 第三方综述文章，具体倍数以官方论文/仓库为准。</p></blockquote><h2 id="延伸" tabindex="-1">延伸 <a class="header-anchor" href="#延伸" aria-label="Permalink to “延伸”">​</a></h2>',12)),a("ul",null,[e[5]||(e[5]=a("li",null,"模型总览见 [[DeepSeek]]",-1)),a("li",null,[e[1]||(e[1]=t("配套的训练/推理工具见 ",-1)),l(n,{href:"/knowledge/vault/Knowledge/AI/DeepSeek 开源周五大工具.html"},{default:o(()=>[...e[0]||(e[0]=[t("DeepSeek 开源周五大工具",-1)])]),_:1})]),a("li",null,[e[3]||(e[3]=t("来源剪藏：",-1)),l(n,{href:"https://blog.csdn.net/anneCoder/article/details/147719340",target:"_blank",rel:"noreferrer"},{default:o(()=>[...e[2]||(e[2]=[t("CSDN 原文",-1)])]),_:1}),e[4]||(e[4]=t("（访问于 2026-07-17）",-1))])]),l(s),l(i)])}const x=d(h,[["render",g]]);export{c as __pageData,x as default};
